import collections
import os
import sys

_CALLS = collections.Counter()
_WATCH_PY = {"compile", "sub", "findall"}
_WATCH_C = {"sorted", "index", "execute", "executemany", "commit", "sum", "lower", "join", "count"}
_HERE = os.getcwd()


def _prof(frame, event, arg):
    if event == "call":
        co = frame.f_code
        fn = co.co_filename
        if fn.startswith(_HERE):
            _CALLS[f"{os.path.relpath(fn, _HERE)}:{co.co_name}"] += 1
        elif co.co_name in _WATCH_PY and "/re/" in fn:
            _CALLS[f"re.{co.co_name}"] += 1
    elif event == "c_call":
        name = getattr(arg, "__name__", "")
        if name in _WATCH_C:
            _CALLS[f"builtin:{name}"] += 1


def profile(fn, *args):
    sys.setprofile(_prof)
    try:
        return fn(*args)
    finally:
        sys.setprofile(None)


def report():
    print("=== profile ===")
    print("%9s  %s" % ("calls", "function"))
    for key, n in _CALLS.most_common(10):
        print("%9d  %s" % (n, key))
    print("=== end ===")

from slotbook.slots import conflicts, free_slots, merge_busy, minutes

BUSY = [(minutes("08:00") + (i * 37) % 560, minutes("08:00") + (i * 37) % 560 + 10 + (i * 11) % 50) for i in range(70)]
EVENTS = [(1000 + i, minutes("08:00") + (i * 53) % 600, minutes("08:00") + (i * 53) % 600 + 5 + (i * 7) % 40) for i in range(130)]


def day():
    merged = merge_busy(BUSY)
    free = free_slots(BUSY, minutes("08:00"), minutes("18:00"), 30)
    clashes = conflicts(EVENTS)
    return len(merged), merged[:2], free[:3], len(clashes), clashes[:3]


result = profile(day)
print("merged ranges, first two, first free slots, clashes, first clashes:")
print(result)
report()

