            good = check_field(name, rule, data[name])
        except ValueError as e:
            finish(0.0, str(e))
        print(f"  {name}: {'ok' if good else 'wrong'}")
        ok += 1 if good else 0
    extra = SPEC.get("run")
    if extra:  # fix-too tasks: the repaired code must reproduce the expected output
        total += 1
        try:
