            out = p.stdout + p.stderr
        except subprocess.TimeoutExpired:
            out = ""
        good = out.strip() == extra["expect"].strip()
        print(f"  repaired behaviour: {'ok' if good else 'wrong'}")
        ok += 1 if good else 0
    finish(ok / total)


